commands.script:
if (-not (Get-Command -Name Set-MpPreference -ErrorAction SilentlyContinue)) { return }
$st = $null
try { $st = Get-MpComputerStatus -ErrorAction Stop } catch { return }
if ($null -eq $st -or -not $st.AMServiceEnabled) { return }
try {
    Set-MpPreference -DisableRealtimeMonitoring $false -DisableBehaviorMonitoring $false -DisableIOAVProtection $false -DisableScriptScanning $false -DisableBlockAtFirstSeen $false -ErrorAction Stop
} catch {
    throw ('Defender-Einstellungen nicht aenderbar. Ist der Manipulationsschutz an? Dann unter Windows-Sicherheit > Viren- und Bedrohungsschutz pruefen. ' + $_.Exception.Message)
}

if (-not (Get-Command -Name Enable-MMAgent -ErrorAction SilentlyContinue)) { return }
$svc = Get-Service -Name 'SysMain' -ErrorAction SilentlyContinue
if ($null -eq $svc) { return }
if ($svc.Status -ne 'Running') {
    if ($svc.StartType -eq 'Disabled') { throw 'Der Dienst SysMain ist deaktiviert. Bitte SysMain im Detweak mit auswaehlen und erneut ausfuehren.' }
    Start-Service -Name 'SysMain' -ErrorAction Stop
}
$mm = Get-MMAgent -ErrorAction Stop
if (-not $mm.MemoryCompression) { Enable-MMAgent -MemoryCompression -ErrorAction Stop }
if (-not $mm.ApplicationPreLaunch) { Enable-MMAgent -ApplicationPreLaunch -ErrorAction Stop }

$exe = Join-Path $env:SystemRoot 'System32\fsutil.exe'
$null = & $exe behavior set DisableDeleteNotify 0 2>&1
if ($LASTEXITCODE -ne 0) { throw ('fsutil behavior set DisableDeleteNotify 0 ist fehlgeschlagen (Code ' + $LASTEXITCODE + ').') }

$cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
if (-not $cs.AutomaticManagedPagefile) {
    Set-CimInstance -InputObject $cs -Property @{ AutomaticManagedPagefile = $true } -ErrorAction Stop
}

$exe = Join-Path $env:SystemRoot 'System32\powercfg.exe'
$null = & $exe /hibernate on 2>&1
if ($LASTEXITCODE -ne 0) { throw ('powercfg /hibernate on ist fehlgeschlagen (Code ' + $LASTEXITCODE + '). Manche Geraete unterstuetzen keinen Ruhezustand.') }

if (-not (Get-Command -Name Set-DnsClientServerAddress -ErrorAction SilentlyContinue)) { throw 'Set-DnsClientServerAddress gibt es auf diesem Windows nicht.' }
$failed = @()
foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop | Where-Object { $_.Status -eq 'Up' })) {
    try { Set-DnsClientServerAddress -InterfaceIndex $a.ifIndex -ResetServerAddresses -ErrorAction Stop } catch { $failed += $a.Name }
}
if ($failed.Count -gt 0) { throw ('DNS konnte nicht zurueckgesetzt werden fuer: ' + ($failed -join ', ')) }

if (-not (Get-Command -Name Reset-NetAdapterAdvancedProperty -ErrorAction SilentlyContinue)) { throw 'Reset-NetAdapterAdvancedProperty gibt es auf diesem Windows nicht.' }
$failed = @()
foreach ($a in @(Get-NetAdapter -Physical -ErrorAction Stop)) {
    try { Reset-NetAdapterAdvancedProperty -Name $a.Name -DisplayName '*' -ErrorAction Stop } catch { $failed += $a.Name }
}
if ($failed.Count -gt 0) { throw ('Nicht zurueckgesetzt (Treiber unterstuetzt es nicht): ' + ($failed -join ', ')) }

$base = Join-Path $env:SystemRoot 'System32'
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
foreach ($name in @('GroupPolicy', 'GroupPolicyUsers')) {
    $dir = Join-Path $base $name
    if (-not (Test-Path -LiteralPath $dir)) { continue }
    Copy-Item -LiteralPath $dir -Destination (Join-Path $base ($name + '.velox-backup-' + $stamp)) -Recurse -Force -ErrorAction Stop
    if ($name -eq 'GroupPolicyUsers') {
        Get-ChildItem -LiteralPath $dir -Force -ErrorAction Stop | Remove-Item -Recurse -Force -ErrorAction Stop
    } else {
        foreach ($sub in @('Machine', 'User')) {
            $pol = Join-Path (Join-Path $dir $sub) 'Registry.pol'
            if (Test-Path -LiteralPath $pol) { Remove-Item -LiteralPath $pol -Force -ErrorAction Stop }
        }
    }
}
$exe = Join-Path $base 'gpupdate.exe'
$null = & $exe /force 2>&1
if ($LASTEXITCODE -ne 0) { throw ('gpupdate /force meldete Code ' + $LASTEXITCODE + '. Nach dem Neustart werden die Richtlinien trotzdem neu eingelesen.') }

$exe = Join-Path $env:SystemRoot 'System32\netsh.exe'
$null = & $exe winsock reset 2>&1
if ($LASTEXITCODE -ne 0) { throw ('netsh winsock reset ist fehlgeschlagen (Code ' + $LASTEXITCODE + ').') }
$null = & $exe int ip reset 2>&1
if ($LASTEXITCODE -ne 0) { throw ('netsh int ip reset meldete Code ' + $LASTEXITCODE + '. Einzelne geschuetzte Eintraege werden oft nicht zurueckgesetzt - das ist meist harmlos. Bitte neu starten.') }
